using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;public static class CleanupModelStage{public static string Run(){int n=0;foreach(var g in Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(a=>a.gameObject.name=="Mage - Peregrino velado"&&!a.GetComponentsInChildren<Renderer>().Any()).ToArray()){Object.DestroyImmediate(g.gameObject);n++;}return "Removed failed-build temporary roots: "+n+"; scene="+SceneManager.GetActiveScene().path;}}
